1	package app
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/parser"
7		"go/token"
8		"sort"
9		"strconv"
10		"strings"
11		"testing"
12	
13		tea "github.com/charmbracelet/bubbletea"
14	
15		"github.com/charmbracelet/x/ansi"
16	
17		"github.com/anthnel/devdesk/internal/command"
18		"github.com/anthnel/devdesk/internal/jobs"
19		"github.com/anthnel/devdesk/internal/ports"
20		"github.com/anthnel/devdesk/internal/template"
21		"github.com/anthnel/devdesk/internal/ui/components"
22		"github.com/anthnel/devdesk/internal/ui/datatable"
23		"github.com/anthnel/devdesk/internal/ui/help"
24		"github.com/anthnel/devdesk/internal/ui/indicator"
25		"github.com/anthnel/devdesk/internal/ui/keymap"
26		"github.com/anthnel/devdesk/internal/ui/netdiag"
27		"github.com/anthnel/devdesk/internal/ui/testutil"
28	)
29	
30	// A-16 (DEVDESK-143), the cross-cutting guard, started with the :jobs pilot
31	// (DEVDESK-142).
32	//
33	// The guard answers one question for every view the router can build: is it on
34	// the activity column, is it waiting for its migration, or is it exempt for a
35	// stated reason? A view that is none of the three fails the test by name. For a
36	// migrated view it also checks the column, the help legend, the retired
37	// mechanisms in its declared sources (including its own ticks), and the footer
38	// of its selected row. Declared exceptions may only shrink, and follow their
39	// stories: pendingTables here, declaredRowChains in animation_guard_test.go.
40	
41	// activityView is what a migrated view exposes to the guard: read-only tables,
42	// keyed "<view>/<table>".
43	type activityView interface {
44		ActivityTables() map[string]datatable.ActivityTable
45	}
46	
47	// migratedTables are the tables already on the activity column, by view.
48	var migratedTables = map[command.ViewType][]string{
49		command.ViewJobs:         {"jobs/runs", "jobs/targets"},
50		command.ViewWorkspaces:   {"ws"},
51		command.ViewSecurity:     {"sec/inventory"},
52		command.ViewOCIResources: {"oci/images", "oci/networks", "oci/volumes", "oci/registries"},
53		command.ViewGitExplorer:  {"explorer/tree", "explorer/clone-list"},
54		command.ViewTemplates:    {"templates"},
55		command.ViewNetdiag:      {"netdiag/ports"},
56		command.ViewAgentUsage:   {"agent-usage/agents"},
57		command.ViewContainers:   {"containers"},
58	}
59	
60	// pendingTable is a table that still has to move to the activity column.
61	type pendingTable struct {
62		Table string
63		View  command.ViewType
64		Story string
65	}
66	
67	// pendingTables may only shrink: each migration story removes its own entries.
68	var pendingTables = []pendingTable{
69		{"oci/registry-browser", command.ViewOCIResources, "A-09a2"},
70	}
71	
72	// maxPendingTables is the ceiling: adding an exception means raising both the
73	// list and this constant in the same diff, which is visible in review. Lower it
74	// with every migration.
75	const maxPendingTables = 1
76	
77	// exemptViews have no long-running operation to show per row (inventory:
78	// "sans objet" or out of the batch), each with its reason.
79	var exemptViews = map[command.ViewType]string{
80		command.ViewDashboard:     "no table with row operations; the dashboard is a summary",
81		command.ViewStatus:        "monitors are polled as a whole, not per-row operations",
82		command.ViewGitAuth:       "a form, no table",
83		command.ViewConfiguration: "a form of settings, no table of operations",
84		command.ViewAbout:         "static facts, no table",
85		command.ViewFiles:         "out of the batch, candidate for a later S story (the delete goes through the registry, no story covers it)",
86		command.ViewViewer:        "a document pane, no table",
87	}
88	
89	func pendingViews() map[command.ViewType][]pendingTable {
90		out := map[command.ViewType][]pendingTable{}
91		for _, p := range pendingTables {
92			out[p.View] = append(out[p.View], p)
93		}
94		return out
95	}
96	
97	func TestActivityGuardPendingListOnlyShrinks(t *testing.T) {
98		if got := len(pendingTables); got > maxPendingTables {
99			t.Errorf("pendingTables has %d entries, ceiling is %d: the list may only shrink (A-16 criterion 6)", got, maxPendingTables)
100		}
101		seen := map[string]bool{}
102		for _, p := range pendingTables {
103			if p.Story == "" {
