477	// retiredMechanisms reports, in a migrated view's file, every retired
478	// mechanism: AdvanceSpinner, a StatusColumn: key, a frame field, an activity
479	// glyph literal, and any reference to bubbletea's Tick / Every (under whatever name the file
480	// imports it) outside declaredViewTicks.
481	// rel is the file's path relative to internal/; it is the key of a declared tick.
482	// RenderedFrame (a method of the viewport frame) is allowed.
483	func retiredMechanisms(fset *token.FileSet, file *ast.File, rel string) []finding {
484		var out []finding
485		report := func(pos token.Pos, what string) {
486			out = append(out, finding{Pos: fset.Position(pos), What: what})
487		}
488		tea := bubbleTeaName(file)
489		selectors := map[*ast.Ident]bool{} // identifiers seen as the Sel of a selector
490		// reportTick flags any reference to bubbletea's Tick / Every, called or not
491		// (`var tick = tea.Tick` is as much a tick as `tea.Tick(...)`), unless the
492		// enclosing "<file>:<function>" is declared.
493		reportTick := func(pos token.Pos, fn, name string) {
494			if name != "Tick" && name != "Every" {
495				return
496			}
497			if _, declared := declaredViewTicks[rel+":"+fn]; !declared {
498				report(pos, "reference to bubbletea's "+name+" (a view's rows are animated by the router's tick)")
499			}
500		}
501		isFrame := func(name string) bool {
502			return name == "Frame" || name == "frame" || name == "SpinnerFrame"
503		}
504		visit := func(fn string) func(ast.Node) bool {
505			return func(n ast.Node) bool {
506				switch x := n.(type) {
507				case *ast.CallExpr:
508					sel, ok := x.Fun.(*ast.SelectorExpr)
509					if !ok {
510						break
511					}
512					if sel.Sel.Name == "AdvanceSpinner" {
513						report(x.Pos(), "call to AdvanceSpinner")
514					}
515				case *ast.KeyValueExpr:
516					if id, ok := x.Key.(*ast.Ident); ok {
517						if id.Name == "StatusColumn" {
518							report(id.Pos(), "StatusColumn: key")
519						}
520						if isFrame(id.Name) {
521							report(id.Pos(), "frame field "+id.Name+": set")
522						}
523					}
524				case *ast.Field:
525					for _, id := range x.Names {
526						if isFrame(id.Name) {
527							report(id.Pos(), "frame field "+id.Name)
528						}
529					}
530				case *ast.Ident:
531					// Dot import: a bare Tick / Every that no declaration in the file binds.
532					if tea == "." && x.Obj == nil && !selectors[x] {
533						reportTick(x.Pos(), fn, x.Name)
534					}
535				case *ast.SelectorExpr:
536					selectors[x.Sel] = true
537					if pkg, ok := x.X.(*ast.Ident); ok && tea != "" && tea != "." && pkg.Name == tea {
538						reportTick(x.Pos(), fn, x.Sel.Name)
539					}
540					if isFrame(x.Sel.Name) {
541						report(x.Sel.Pos(), "frame selector ."+x.Sel.Name)
542					}
543				case *ast.BasicLit:
544					if x.Kind == token.STRING || x.Kind == token.CHAR {
545						s, err := strconv.Unquote(x.Value)
546						if x.Kind == token.CHAR {
547							var q rune
548							q, _, _, err = strconv.UnquoteChar(x.Value[1:len(x.Value)-1], '\'')
549							s = string(q)
550						}
551						if err == nil && strings.ContainsAny(s, activityGlyphs) {
552							report(x.Pos(), "activity glyph written as a literal "+x.Value+" (use indicator.Glyph)")
553						}
554					}
555				}
556				return true
557			}
558		}
559		for _, decl := range file.Decls {
560			fn := ""
561			if fd, ok := decl.(*ast.FuncDecl); ok {
562				fn = fd.Name.Name
563			}
564			if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.CONST {
565				for _, spec := range gd.Specs {
566					if isDeclaredGlyphConstant(rel, spec) {
567						continue
568					}
569					ast.Inspect(spec, visit(fn))
570				}
571				continue
572			}
573			ast.Inspect(decl, visit(fn))
574		}
575		return out
576	}
577	
578	// isDeclaredGlyphConstant reports whether spec defines only constants declared in
579	// declaredGlyphConstants for the file rel.
580	func isDeclaredGlyphConstant(rel string, spec ast.Spec) bool {
581		vs, ok := spec.(*ast.ValueSpec)
582		if !ok || len(vs.Names) == 0 {
583			return false
584		}
585		for _, id := range vs.Names {
586			if _, declared := declaredGlyphConstants[rel+":"+id.Name]; !declared {
587				return false
588			}
589		}
590		return true
591	}
